INSERT INTO chb_investhold_info
SELECT  REGIST_BANK_CODE,  INDENTIFY_MARK,  PRD_REGIST_CODE,  DATE_ADD(HOLD_DATE,INTERVAL 1 DAY),  CCY,  AMOUNT,  QTY,  CNY_AMT, REMARK,  DATA_SOURCE,  STATUS,  WORKFLOW_ID,  ORG_CODE,  DEPT_CODE,  UPDATE_USER,  NOW(),  CREATE_USER,  NOW(),  AGENT,  CREATE_DEPT,  PRODID, INTERF_CHECK_RESULT
FROM chb_investhold_info WHERE HOLD_DATE = #{holdDate}
